-- NON-ACTIVE DRAFT ONLY. No authorization to execute. Proposed future version: 20261011120000.
-- Based on 20261010120000 fidelity baseline; NOT an entitlement-security completion.
-- user_plans browser INSERT/UPDATE remains a documented critical blocker.
-- No application rows, platform objects, buckets, history, or sequence values are changed.
BEGIN;
SET LOCAL search_path = pg_catalog, public;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

DO $preflight$
DECLARE actual jsonb; expected jsonb; f record; d record; history_ok boolean;
BEGIN
 IF current_setting('hirefit.security_review_target',true) IS DISTINCT FROM 'isolated-reviewed-security-target'
    OR current_user <> 'postgres' OR current_setting('server_version_num')::int / 10000 <> 17 THEN
   RAISE EXCEPTION 'DRAFT: separately authorized isolated target, postgres and PostgreSQL 17 required';
 END IF;
 -- A session marker is NOT identity proof. External disposable-project verification is mandatory.
 IF to_regclass('supabase_migrations.schema_migrations') IS NULL THEN
   RAISE EXCEPTION 'Reviewed baseline history prerequisite missing; do not create it for this test';
 END IF;
 EXECUTE 'SELECT count(*)=1 AND bool_and(version::text=''20261010120000'' AND name=''production_state_baseline'') FROM supabase_migrations.schema_migrations' INTO history_ok;
 IF history_ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'Unexpected baseline history'; END IF;
 -- Acquire table locks before inspecting mutable table ACL/policy state.
 LOCK TABLE public.analyses, public.career_companion_cases, public.career_companion_outcomes, public.career_profiles, public.career_progress_snapshots, public.opportunities, public.opportunity_location_preferences, public.opportunity_locations, public.opportunity_user_states, public.profiles, public.user_plans, public.waitlist IN ACCESS EXCLUSIVE MODE;
 IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
     WHERE n.nspname='public' AND c.relname=ANY(ARRAY['analyses', 'career_companion_cases', 'career_companion_outcomes', 'career_profiles', 'career_progress_snapshots', 'opportunities', 'opportunity_location_preferences', 'opportunity_locations', 'opportunity_user_states', 'profiles', 'user_plans', 'waitlist'])
       AND c.relkind='r' AND c.relowner='postgres'::regrole AND c.relrowsecurity AND NOT c.relforcerowsecurity) <> 12 THEN
   RAISE EXCEPTION 'Baseline table ownership/RLS/inventory differs';
 END IF;
 IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname IN ('anon','authenticated')
      AND (rolsuper OR rolbypassrls))
    OR NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role' AND rolbypassrls AND NOT rolsuper)
    OR EXISTS (SELECT 1 FROM pg_auth_members WHERE member IN ('anon'::regrole,'authenticated'::regrole,'service_role'::regrole))
    OR has_schema_privilege('anon','public','CREATE')
    OR has_schema_privilege('authenticated','public','CREATE')
    OR has_schema_privilege('service_role','public','CREATE') THEN
   RAISE EXCEPTION 'Role inheritance/attributes/schema CREATE differ; do not adjust platform roles';
 END IF;
 IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid
    JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'
    AND c.relname=ANY(ARRAY['analyses', 'career_companion_cases', 'career_companion_outcomes', 'career_profiles', 'career_progress_snapshots', 'opportunities', 'opportunity_location_preferences', 'opportunity_locations', 'opportunity_user_states', 'profiles', 'user_plans', 'waitlist','user_plans_id_seq']) AND a.attacl IS NOT NULL) THEN
   RAISE EXCEPTION 'Unexpected column ACL';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_attribute a ON a.attrelid=c.oid
    WHERE c.oid='public.user_plans'::regclass AND a.attname='id' AND a.attidentity='d')
    OR pg_get_serial_sequence('public.user_plans','id') IS DISTINCT FROM 'public.user_plans_id_seq'
    OR NOT EXISTS (SELECT 1 FROM pg_sequence s JOIN pg_class c ON c.oid=s.seqrelid
