DO $postconditions$
DECLARE t text; r text; p text; allowed jsonb := $allowed${"analyses":{"authenticated":["SELECT","INSERT"]},"career_companion_cases":{"service_role":["SELECT","INSERT","UPDATE","DELETE"]},"career_companion_outcomes":{"service_role":["SELECT","INSERT","UPDATE"]},"career_profiles":{"service_role":["SELECT","INSERT","UPDATE"]},"career_progress_snapshots":{"service_role":["SELECT","INSERT"]},"opportunities":{"service_role":["SELECT"]},"opportunity_location_preferences":{"service_role":["SELECT","INSERT","UPDATE","DELETE"]},"opportunity_locations":{"service_role":["SELECT"]},"opportunity_user_states":{"service_role":["SELECT","INSERT","UPDATE"]},"profiles":{},"user_plans":{"authenticated":["SELECT","INSERT","UPDATE"],"service_role":["SELECT","INSERT","UPDATE"]},"waitlist":{}}$allowed$::jsonb;
 actual jsonb; expected jsonb;
BEGIN
 FOREACH t IN ARRAY ARRAY['analyses', 'career_companion_cases', 'career_companion_outcomes', 'career_profiles', 'career_progress_snapshots', 'opportunities', 'opportunity_location_preferences', 'opportunity_locations', 'opportunity_user_states', 'profiles', 'user_plans', 'waitlist'] LOOP
   IF NOT EXISTS (SELECT 1 FROM pg_class WHERE oid=('public.'||t)::regclass
       AND relowner='postgres'::regrole AND relrowsecurity AND NOT relforcerowsecurity) THEN
     RAISE EXCEPTION 'RLS/owner changed: %',t;
   END IF;
   FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
     FOREACH p IN ARRAY ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER','MAINTAIN'] LOOP
       IF has_table_privilege(r,('public.'||t)::regclass,p)
          IS DISTINCT FROM coalesce((allowed->t->r) ? p,false) THEN
          RAISE EXCEPTION 'Unexpected effective privilege %.% %',t,r,p;
       END IF;
     END LOOP;
   END LOOP;
 END LOOP;
 FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
   FOREACH p IN ARRAY ARRAY['SELECT','UPDATE','USAGE'] LOOP
     IF has_sequence_privilege(r,'public.user_plans_id_seq',p) THEN
       RAISE EXCEPTION 'Unexpected sequence privilege % %',r,p;
     END IF;
   END LOOP;
   IF has_function_privilege(r,'public.increment_user_plan_analysis(uuid)','EXECUTE')
      IS DISTINCT FROM (r='authenticated') THEN RAISE EXCEPTION 'RPC effective ACL unexpected'; END IF;
   IF has_function_privilege(r,'public.opportunity_radar_touch_updated_at()','EXECUTE')
      IS DISTINCT FROM (r='service_role') THEN RAISE EXCEPTION 'Trigger effective ACL unexpected'; END IF;
 END LOOP;
 IF (SELECT proconfig FROM pg_proc WHERE oid='public.increment_user_plan_analysis(uuid)'::regprocedure)
     IS DISTINCT FROM ARRAY['search_path=pg_catalog, pg_temp']::text[] THEN RAISE EXCEPTION 'RPC search_path unexpected'; END IF;
 SELECT coalesce(jsonb_agg(item),'[]'::jsonb) INTO actual FROM (SELECT jsonb_build_object('object',n.nspname||'.'||c.relname||'.'||p.polname,
 'roles',(SELECT jsonb_agg(CASE WHEN roleid=0 THEN 'PUBLIC' ELSE pg_get_userbyid(roleid)::text END ORDER BY roleid) FROM unnest(p.polroles) roleid),
 'using',pg_get_expr(p.polqual,p.polrelid),'command',p.polcmd::text,'permissive',p.polpermissive,
 'with_check',pg_get_expr(p.polwithcheck,p.polrelid)) AS item
 FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND c.relname=ANY(ARRAY['analyses', 'career_companion_cases', 'career_companion_outcomes', 'career_profiles', 'career_progress_snapshots', 'opportunities', 'opportunity_location_preferences', 'opportunity_locations', 'opportunity_user_states', 'profiles', 'user_plans', 'waitlist'])) v;
 expected := $expected_policies$[{"object":"public.analyses.analyses_delete_own","roles":["authenticated"],"using":"(auth.uid() = user_id)","command":"d","permissive":true,"with_check":null},{"object":"public.analyses.analyses_insert_own","roles":["authenticated"],"using":null,"command":"a","permissive":true,"with_check":"(auth.uid() = user_id)"},{"object":"public.analyses.analyses_select_own","roles":["authenticated"],"using":"(auth.uid() = user_id)","command":"r","permissive":true,"with_check":null},{"object":"public.analyses.analyses_update_own","roles":["authenticated"],"using":"(auth.uid() = user_id)","command":"w","permissive":true,"with_check":"(auth.uid() = user_id)"},{"object":"public.career_companion_cases.career_companion_cases_own","roles":["authenticated"],"using":"(auth.uid() = user_id)","command":"*","permissive":true,"with_check":"(auth.uid() = user_id)"},{"object":"public.career_companion_outcomes.career_companion_outcomes_own","roles":["authenticated"],"using":"(auth.uid() = user_id)","command":"*","permissive":true,"with_check":"(auth.uid() = user_id)"},{"object":"public.career_profiles.career_profiles_delete_own","roles":["authenticated"],"using":"(auth.uid() = user_id)","command":"d","permissive":true,"with_check":null},{"object":"public.career_profiles.career_profiles_insert_own","roles":["authenticated"],"using":null,"command":"a","permissive":true,"with_check":"(auth.uid() = user_id)"},{"object":"public.career_profiles.career_profiles_select_own","roles":["authenticated"],"using":"(auth.uid() = user_id)","command":"r","permissive":true,"with_check":null},{"object":"public.career_profiles.career_profiles_update_own","roles":["authenticated"],"using":"(auth.uid() = user_id)","command":"w","permissive":true,"with_check":"(auth.uid() = user_id)"},{"object":"public.career_progress_snapshots.career_progress_delete_own","roles":["authenticated"],"using":"(auth.uid() = user_id)","command":"d","permissive":true,"with_check":null},{"object":"public.career_progress_snapshots.career_progress_insert_own","roles":["authenticated"],"using":null,"command":"a","permissive":true,"with_check":"(auth.uid() = user_id)"},{"object":"public.career_progress_snapshots.career_progress_select_own","roles":["authenticated"],"using":"(auth.uid() = user_id)","command":"r","permissive":true,"with_check":null},{"object":"public.opportunities.opportunities_read_verified_jobs","roles":["authenticated"],"using":"((type = 'job'::text) AND published AND active AND (verification_status = 'verified'::text) AND (source_type <> 'fixture'::text) AND (last_verified_at <= now()) AND (expires_at > now()) AND ((deadline_at IS NULL) OR (deadline_at > now())) AND ((ends_at IS NULL) OR (ends_at > now())))","command":"r","permissive":true,"with_check":null},{"object":"public.opportunity_user_states.opportunity_user_states_read_own","roles":["authenticated"],"using":"(auth.uid() = user_id)","command":"r","permissive":true,"with_check":null},{"object":"public.user_plans.\"Users can insert own plan\"","roles":["PUBLIC"],"using":null,"command":"a","permissive":true,"with_check":"((auth.uid())::text = user_id)"},{"object":"public.user_plans.\"Users can read own plan\"","roles":["PUBLIC"],"using":"((auth.uid())::text = user_id)","command":"r","permissive":true,"with_check":null},{"object":"public.user_plans.\"Users can update own plan\"","roles":["PUBLIC"],"using":"((auth.uid())::text = user_id)","command":"w","permissive":true,"with_check":null}]$expected_policies$::jsonb;
 IF jsonb_array_length(actual)<>jsonb_array_length(expected) OR NOT(actual @> expected AND expected @> actual) THEN
   RAISE EXCEPTION 'Policies changed unexpectedly';
 END IF;
 IF EXISTS (SELECT 1 FROM pg_default_acl d,LATERAL aclexplode(d.defaclacl) a
   WHERE d.defaclrole='postgres'::regrole AND d.defaclnamespace='public'::regnamespace
